// Verify over the exact bytes received. The webhook's Raw Body option keeps them; the
// parsed JSON would not reproduce the signature if whitespace or key order differed.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBody = raw.toString('utf8');
const headers = $input.first().json.headers;
const timestamp = headers['x-lendloop-timestamp'] ?? '';
return [{ json: {
  rawBody,
  timestamp,
  receivedSignature: headers['x-lendloop-signature'] ?? '',
  signingInput: `${timestamp}.${rawBody}`,
} }];

// The Crypto node computed the expected HMAC using the credential. This node only
// compares digests, so it never has access to the secret.
const crypto = require('crypto');
const TOLERANCE_SECONDS = 300;

const { rawBody, timestamp, receivedSignature, signature: expected } = $json;
const fresh = /^\d{1,12}$/.test(timestamp)
  && Math.abs(Date.now() / 1000 - Number(timestamp)) <= TOLERANCE_SECONDS;
const received = Buffer.from(receivedSignature, 'utf8');
const wanted = Buffer.from(expected, 'utf8');
// timingSafeEqual throws on different lengths; length is not a secret, so check it first.
const matches = received.length === wanted.length && crypto.timingSafeEqual(received, wanted);

if (!fresh || !matches) {
  console.log(`[notify] rejected webhook: ${fresh ? 'bad signature' : 'stale or missing timestamp'}`);
  return { valid: false };
}
return { valid: true, payload: JSON.parse(rawBody) };

// Claim before sending: if Convex retries this webhook, the duplicate run loses the claim.
const { payload } = $json;
return {
  method: 'POST',
  path: '/n8n/activity',
  body: JSON.stringify({ idempotencyKey: payload.eventId, kind: 'notification', status: 'sending', loanId: payload.loanId }),
  context: payload,
};

const mask = (email) => email.replace(/^(.).*(@.*)$/, '$1***$2');

// Mock notification: writes to the container log and this execution's output. An address
// ending in @bounce.test simulates a delivery failure, for demoing the failure path.
const event = $json.context;
const SUBJECTS = {
  pending: `New request to borrow your ${event.toolName}`,
  approved: `Your request for ${event.toolName} was approved`,
  declined: `Your request for ${event.toolName} was declined`,
  cancelled: `A request for your ${event.toolName} was cancelled`,
  returned: `Your loan of ${event.toolName} is marked returned`,
};
const delivered = !event.recipientEmail.endsWith('@bounce.test');
// Addresses are masked so logs do not accumulate personal data.
console.log(JSON.stringify({ channel: 'mock-notification', to: mask(event.recipientEmail), subject: SUBJECTS[event.status], delivered }));
return {
  method: 'POST',
  path: '/n8n/activity',
  body: JSON.stringify({
    idempotencyKey: event.eventId,
    kind: 'notification',
    status: delivered ? 'sent' : 'failed',
    loanId: event.loanId,
    detail: delivered ? undefined : 'Mock delivery failed',
  }),
  context: { idempotencyKey: event.eventId, delivered },
};

// Runs after every item has been written back, so one bad recipient does not stop the
// others. Throwing here marks the run failed, which triggers the Error Workflow.
const failed = $input.all().filter((item) => item.json.context.delivered === false);
if (failed.length > 0) {
  throw new Error(`${failed.length} of ${$input.all().length} notification(s) failed: ${failed.map((item) => item.json.context.idempotencyKey).join(', ')}`);
}
return [{ json: { sent: $input.all().length } }];
